282	// to a view chaining the stages through messages.
283	func TestRunStepWalksTheSamePipelineAsRun(t *testing.T) {
284		env := fakeEnv{
285			dial: func(context.Context, string) (time.Duration, error) {
286				return 0, errors.New("connection refused")
287			},
288		}
289	
290		whole, err := Run(context.Background(), target(), env, DefaultSettings())
291		if err != nil {
292			t.Fatalf("Run: %v", err)
293		}
294	
295		var piecewise Results
296		for _, id := range Steps() {
297			piecewise = RunStep(context.Background(), target(), env, DefaultSettings(), id, piecewise)
298		}
299	
300		if len(piecewise.All()) != len(whole.All()) {
301			t.Fatalf("piecewise produced %d checks, Run produced %d", len(piecewise.All()), len(whole.All()))
302		}
303		for i, c := range whole.All() {
304			got := piecewise.All()[i]
305			if got.ID != c.ID || got.Verdict != c.Verdict || got.Because != c.Because {
306				t.Errorf("check %d: piecewise %s/%s/%s, Run %s/%s/%s",
307					i, got.ID, got.Verdict, got.Because, c.ID, c.Verdict, c.Because)
308			}
309		}
310	}
