313	// caller depends on: the previous value is held by the model while the next
314	// stage runs on a goroutine, so a shared backing array would be a data race on
315	// the one thing Rule 110 exists to prevent.
316	func TestRunStepDoesNotWriteIntoTheResultsItWasGiven(t *testing.T) {
317		first := RunStep(context.Background(), target(), fakeEnv{}, DefaultSettings(), StageResolve, Results{})
318		snapshot := len(first.All())
319	
320		RunStep(context.Background(), target(), fakeEnv{}, DefaultSettings(), StageReach, first)
321		RunStep(context.Background(), target(), fakeEnv{}, DefaultSettings(), StageConnect, first)
322	
323		if len(first.All()) != snapshot {
324			t.Fatalf("the earlier Results grew from %d to %d checks", snapshot, len(first.All()))
325		}
326	}
