330	func TestEveryStageIsNamedForAProgressLine(t *testing.T) {
331		for _, id := range Steps() {
332			if StageTitle(id) == "" {
333				t.Errorf("stage %q has no title", id)
334			}
335		}
336		if len(Steps()) != len(stages()) {
337			t.Errorf("Steps() reports %d stages, the pipeline has %d", len(Steps()), len(stages()))
338		}
339	}
