func TestVerdictNamesAreShortEnoughForATableCell(t *testing.T) {
	for _, v := range []Verdict{Unknown, NotApplicable, OK, Warn, Fail} {
		if n := len(v.String()); n == 0 || n > 7 {
			t.Errorf("%d renders as %q (%d chars)", int(v), v.String(), n)
